customStyles:
@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,700;0,900;1,400;1,700&family=Inconsolata:wght@300;400;500;700&display=swap');

:root {
  --chess-black:   #0a0a0a;
  --chess-dark:    #111111;
  --chess-mid:     #1a1a1a;
  --chess-border:  #2a2a2a;
  --chess-white:   #f0ede6;
  --chess-cream:   #c8c2b4;
  --chess-gold:    #c9a84c;
  --chess-gold-dim:#8a6f2e;
  --chess-red:     #8b1a1a;
  --chess-red-lit: #c0392b;
  --font-display:  'Playfair Display', Georgia, serif;
  --font-mono:     'Inconsolata', 'Courier New', monospace;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  background: var(--chess-black);
  color: var(--chess-white);
  font-family: var(--font-mono);
  font-size: 16px;
  line-height: 1.7;
  min-height: 100vh;
}

/* ── CHESS BOARD PATTERN ── */
.chess-bg {
  position: fixed; inset: 0; z-index: 0; pointer-events: none;
  background-image:
    repeating-conic-gradient(
      rgba(255,255,255,0.015) 0% 25%,
      transparent 0% 50%
    );
  background-size: 48px 48px;
}

/* ── LAYOUT SHELL ── */
.site-shell {
  position: relative; z-index: 1;
  display: flex; flex-direction: column; min-height: 100vh;
}

/* ── HEADER ── */
.site-header {
  position: sticky; top: 0; z-index: 100;
  background: rgba(10,10,10,0.96);
  border-bottom: 1px solid var(--chess-border);
  backdrop-filter: blur(12px);
  padding: 0 2.5rem;
  display: flex; align-items: center; justify-content: space-between;
  height: 70px;
}

.site-logo {
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 900;
  letter-spacing: -0.02em;
  color: var(--chess-white);
  text-decoration: none;
  display: flex; align-items: center; gap: 0.6rem;
}

.site-logo .logo-icon {
  font-size: 1.4rem;
  filter: drop-shadow(0 0 8px var(--chess-gold));
}

.site-logo span {
  color: var(--chess-gold);
}

.site-nav {
  display: flex; align-items: center; gap: 0.25rem;
}

.site-nav a {
  font-family: var(--font-mono);
  font-size: 0.78rem;
  font-weight: 500;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--chess-cream);
  text-decoration: none;
  padding: 0.4rem 0.9rem;
  border: 1px solid transparent;
  transition: all 0.2s ease;
}

.site-nav a:hover {
  color: var(--chess-gold);
  border-color: var(--chess-gold-dim);
  background: rgba(201,168,76,0.06);
}

/* ── MAIN CONTENT AREA ── */
.site-main {
  flex: 1;
  display: grid;
  grid-template-columns: 1fr 300px;
  gap: 0;
  max-width: 1280px;
  margin: 0 auto;
  width: 100%;
  padding: 3rem 2.5rem;
}

.site-main.no-sidebar {
  grid-template-columns: 1fr;
  max-width: 860px;
}

.main-content { min-width: 0; padding-right: 3rem; }
.site-main.no-sidebar .main-content { padding-right: 0; }

/* ── HERO ── */
.hero-block {
  position: relative;
  padding: 4rem 0 3rem;
  margin-bottom: 3rem;
  border-bottom: 1px solid var(--chess-border);
}

.hero-label {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  letter-spacing: 0.25em;
  text-transform: uppercase;
  color: var(--chess-gold);
  margin-bottom: 1rem;
  display: flex; align-items: center; gap: 0.75rem;
}

.hero-label::before {
  content: '';
  display: block; width: 2rem; height: 1px;
  background: var(--chess-gold);
}

.hero-title {
  font-family: var(--font-display);
  font-size: clamp(2.8rem, 6vw, 5rem);
  font-weight: 900;
  line-height: 1.05;
  letter-spacing: -0.02em;
  color: var(--chess-white);
  margin-bottom: 1.25rem;
}

.hero-title em {
  font-style: italic;
  color: var(--chess-gold);
}

.hero-sub {
  font-size: 1rem;
  color: var(--chess-cream);
  max-width: 540px;
  margin-bottom: 2rem;
  opacity: 0.8;
}

.hero-ctas {
  display: flex; gap: 1rem; flex-wrap: wrap;
}

/* ── BUTTONS ── */
.btn {
  display: inline-flex; align-items: center; gap: 0.5rem;
  font-family: var(--font-mono);
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  text-decoration: none;
  padding: 0.75rem 1.5rem;
  border: 1px solid;
  transition: all 0.2s ease;
  cursor: pointer;
}

.btn-primary {
  background: var(--chess-gold);
  border-color: var(--chess-gold);
  color: var(--chess-black);
}

.btn-primary:hover {
  background: transparent;
  color: var(--chess-gold);
}

.btn-secondary {
  background: transparent;
  border-color: var(--chess-border);
  color: var(--chess-cream);
}

.btn-secondary:hover {
  border-color: var(--chess-gold);
  color: var(--chess-gold);
}

/* ── POST GRID ── */
.posts-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 1.5px;
  background: var(--chess-border);
  border: 1px solid var(--chess-border);
  margin-bottom: 3rem;
}

.post-card {
  background: var(--chess-dark);
  padding: 1.75rem;
  text-decoration: none;
  display: flex; flex-direction: column;
  transition: background 0.2s ease;
  position: relative;
  overflow: hidden;
}

.post-card::before {
  content: '';
  position: absolute; top: 0; left: 0;
  width: 3px; height: 0;
  background: var(--chess-gold);
  transition: height 0.3s ease;
}

.post-card:hover { background: var(--chess-mid); }
.post-card:hover::before { height: 100%; }

.post-card-featured {
  grid-column: 1 / -1;
  flex-direction: row;
  gap: 2rem;
  padding: 2.5rem;
}

.post-card-featured .card-img {
  width: 320px; flex-shrink: 0;
  height: 200px;
}

.card-img {
  width: 100%; height: 160px;
  background: var(--chess-mid);
  margin-bottom: 1.25rem;
  overflow: hidden;
  position: relative;
}

.card-img img {
  width: 100%; height: 100%;
  object-fit: cover;
  filter: grayscale(30%) contrast(1.1);
  transition: filter 0.3s ease, transform 0.4s ease;
}

.post-card:hover .card-img img {
  filter: grayscale(0%) contrast(1.0);
  transform: scale(1.04);
}

.card-img-placeholder {
  width: 100%; height: 100%;
  background: repeating-conic-gradient(
    var(--chess-border) 0% 25%, var(--chess-dark) 0% 50%
  ) 0 0 / 24px 24px;
  display: flex; align-items: center; justify-content: center;
  font-size: 2.5rem;
  opacity: 0.4;
}

.card-meta {
  display: flex; align-items: center; gap: 0.75rem;
  margin-bottom: 0.75rem;
}

.card-category {
  font-family: var(--font-mono);
  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--chess-gold);
}

.card-date {
  font-size: 0.65rem;
  color: var(--chess-cream);
  opacity: 0.5;
}

.card-title {
  font-family: var(--font-display);
  font-size: 1.15rem;
  font-weight: 700;
  line-height: 1.3;
  color: var(--chess-white);
  margin-bottom: 0.75rem;
  flex: 1;
  transition: color 0.2s ease;
}

.post-card:hover .card-title { color: var(--chess-gold); }

.post-card-featured .card-title {
  font-size: 1.6rem;
}

.card-excerpt {
  font-size: 0.82rem;
  color: var(--chess-cream);
  opacity: 0.65;
  line-height: 1.6;
  margin-bottom: 1rem;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.card-footer {
  display: flex; align-items: center; justify-content: space-between;
  margin-top: auto;
  padding-top: 1rem;
  border-top: 1px solid var(--chess-border);
}

.card-author {
  font-size: 0.7rem;
  color: var(--chess-cream);
  opacity: 0.5;
}

.card-read-time {
  font-size: 0.65rem;
  color: var(--chess-gold-dim);
  letter-spacing: 0.1em;
}

/* ── SECTION HEADER ── */
.section-header {
  display: flex; align-items: baseline; justify-content: space-between;
  margin-bottom: 1.5rem;
  padding-bottom: 1rem;
  border-bottom: 1px solid var(--chess-border);
}

.section-title {
  font-family: var(--font-display);
  font-size: 1.4rem;
  font-weight: 700;
  color: var(--chess-white);
  display: flex; align-items: center; gap: 0.6rem;
}

.section-title::after {
  content: '';
  display: block; width: 1rem; height: 2px;
  background: var(--chess-gold);
}

.section-link {
  font-size: 0.7rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--chess-gold-dim);
  text-decoration: none;
  transition: color 0.2s;
}

.section-link:hover { color: var(--chess-gold); }

/* ── SIDEBAR ── */
.site-sidebar {
  border-left: 1px solid var(--chess-border);
  padding-left: 2.5rem;
}

.sidebar-widget {
  margin-bottom: 2.5rem;
}

.widget-title {
  font-family: var(--font-mono);
  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 0.25em;
  text-transform: uppercase;
  color: var(--chess-gold);
  margin-bottom: 1.25rem;
  padding-bottom: 0.75rem;
  border-bottom: 1px solid var(--chess-border);
  display: flex; align-items: center; gap: 0.5rem;
}

.recent-post-item {
  display: flex; flex-direction: column;
  padding: 0.85rem 0;
  border-bottom: 1px solid var(--chess-border);
  text-decoration: none;
  transition: padding-left 0.2s ease;
}

.recent-post-item:hover { padding-left: 0.5rem; }

.recent-post-item:last-child { border-bottom: none; }

.recent-post-title {
  font-family: var(--font-display);
  font-size: 0.88rem;
  font-weight: 600;
  color: var(--chess-white);
  line-height: 1.35;
  margin-bottom: 0.2rem;
  transition: color 0.2s;
}

.recent-post-item:hover .recent-post-title { color: var(--chess-gold); }

.category-list { list-style: none; }

.category-item {
  display: flex; align-items: center; justify-content: space-between;
  padding: 0.6rem 0;
  border-bottom: 1px solid var(--chess-border);
}

.category-item:last-child { border-bottom: none; }

.category-link {
  font-size: 0.82rem;
  color: var(--chess-cream);
  text-decoration: none;
  transition: color 0.2s;
  display: flex; align-items: center; gap: 0.5rem;
}

.category-link::before {
  content: '♟';
  font-size: 0.7rem;
  color: var(--chess-gold-dim);
}

.category-link:hover { color: var(--chess-gold); }

.category-count {
  font-size: 0.65rem;
  color: var(--chess-cream);
  opacity: 0.35;
  font-variant-numeric: tabular-nums;
}

.sidebar-board {
  display: grid;
  grid-template-columns: repeat(8, 1fr);
  height:259px;
 gap: 0;
  border: 1px solid var(--chess-border);
  margin-top: 0.5rem;
}

.board-cell {
  aspect-ratio: 1;
  background: var(--chess-dark);
}

.board-cell.light { background: var(--chess-mid); }

.board-cell.has-piece {
  display: flex; align-items: center; justify-content: center;
  font-size: 1.1rem;
  color: var(--chess-gold);
  text-shadow: 0 0 8px rgba(201,168,76,0.6);
}

/* ── SINGLE POST ── */
.post-header {
  padding: 3rem 0 2rem;
  margin-bottom: 2rem;
  border-bottom: 1px solid var(--chess-border);
}

.post-title {
  font-family: var(--font-display);
  font-size: clamp(2rem, 4.5vw, 3.5rem);
  font-weight: 900;
  line-height: 1.1;
  letter-spacing: -0.02em;
  color: var(--chess-white);
  margin-bottom: 1.5rem;
}

.post-meta-bar {
  display: flex; align-items: center; gap: 1.5rem;
  flex-wrap: wrap;
}

.post-meta-item {
  font-size: 0.72rem;
  color: var(--chess-cream);
  opacity: 0.55;
  letter-spacing: 0.08em;
  display: flex; align-items: center; gap: 0.35rem;
}

.post-meta-item.highlight {
  color: var(--chess-gold);
  opacity: 1;
}

.post-featured-img {
  width: 100%;
  aspect-ratio: 16/7;
  object-fit: cover;
  filter: grayscale(20%) contrast(1.1);
  margin-bottom: 2.5rem;
  display: block;
}

.post-content {
  font-size: 1rem;
  line-height: 1.85;
  color: var(--chess-cream);
}

.post-content h2 {
  font-family: var(--font-display);
  font-size: 1.65rem;
  font-weight: 700;
  color: var(--chess-white);
  margin: 2.5rem 0 1rem;
  padding-bottom: 0.5rem;
  border-bottom: 1px solid var(--chess-border);
}

.post-content h3 {
  font-family: var(--font-display);
  font-size: 1.2rem;
  color: var(--chess-white);
  margin: 2rem 0 0.75rem;
}

.post-content p { margin-bottom: 1.5rem; }

.post-content a {
  color: var(--chess-gold);
  text-decoration: underline;
  text-underline-offset: 3px;
}

.post-content blockquote {
  border-left: 3px solid var(--chess-gold);
  padding: 1rem 1.5rem;
  margin: 2rem 0;
  background: var(--chess-mid);
  font-family: var(--font-display);
  font-style: italic;
  font-size: 1.1rem;
  color: var(--chess-white);
}

.post-content code {
  font-family: var(--font-mono);
  font-size: 0.85em;
  background: var(--chess-mid);
  padding: 0.15em 0.4em;
  border: 1px solid var(--chess-border);
  color: var(--chess-gold);
}

.post-content pre {
  background: var(--chess-mid);
  border: 1px solid var(--chess-border);
  padding: 1.5rem;
  overflow-x: auto;
  margin: 1.5rem 0;
}

.post-content pre code {
  background: none; border: none; padding: 0;
}

.post-content img {
  max-width: 100%;
  margin: 1.5rem 0;
  filter: grayscale(15%);
}

.post-content ul, .post-content ol {
  padding-left: 1.5rem;
  margin-bottom: 1.5rem;
}

.post-content li { margin-bottom: 0.4rem; }

/* ── STATIC PAGE ── */
.page-header {
  padding: 3rem 0 2rem;
  border-bottom: 1px solid var(--chess-border);
  margin-bottom: 2rem;
}

.page-title {
  font-family: var(--font-display);
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 900;
  color: var(--chess-white);
}

.page-content {
  font-size: 1rem;
  line-height: 1.85;
  color: var(--chess-cream);
}

.page-content h2 {
  font-family: var(--font-display);
  font-size: 1.5rem;
  color: var(--chess-white);
  margin: 2rem 0 0.75rem;
}

.page-content p { margin-bottom: 1.5rem; }

/* ── CATEGORY PAGE ── */
.category-header {
  padding: 3rem 0 2rem;
  border-bottom: 1px solid var(--chess-border);
  margin-bottom: 2.5rem;
}

.category-badge {
  display: inline-block;
  font-size: 0.65rem;
  letter-spacing: 0.25em;
  text-transform: uppercase;
  color: var(--chess-gold);
  border: 1px solid var(--chess-gold-dim);
  padding: 0.3rem 0.75rem;
  margin-bottom: 1rem;
}

.category-title {
  font-family: var(--font-display);
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 900;
  color: var(--chess-white);
  margin-bottom: 0.5rem;
}

/* ── 404 PAGE ── */
.error-page {
  display: flex; flex-direction: column;
  align-items: center; justify-content: center;
  min-height: 70vh;
  text-align: center;
  padding: 3rem;
}

.error-board {
  display: grid;
  grid-template-columns: repeat(8, 36px);
  grid-template-rows: repeat(8, 36px);
  gap: 0;
  margin-bottom: 3rem;
  border: 2px solid var(--chess-border);
  box-shadow: 0 0 40px rgba(201,168,76,0.1);
}

.error-cell {
  background: var(--chess-dark);
}

.error-cell.light { background: var(--chess-mid); }

.error-cell.gold {
  background: #272006;
}

.error-cell.gold.light-gold {
  background: #332d19;
}

  .error-code {
  font-family: var(--font-display);
  font-size: clamp(5rem, 15vw, 9rem);
  font-weight: 900;
  color: var(--chess-white);
  line-height: 1;
  letter-spacing: -0.05em;
  margin-bottom: 0.5rem;
}

.error-code span { color: var(--chess-gold); }

.error-message {
  font-size: 1rem;
  color: var(--chess-cream);
  opacity: 0.6;
  margin-bottom: 2rem;
}

/* ── FOOTER ── */
.site-footer {
  border-top: 1px solid var(--chess-border);
  padding: 2.5rem;
  display: flex; align-items: center; justify-content: space-between;
  flex-wrap: wrap; gap: 1rem;
  background: var(--chess-dark);
}

.footer-brand {
  font-family: var(--font-display);
  font-size: 1rem;
  font-weight: 700;
  color: var(--chess-gold);
}

.footer-copy {
  font-size: 0.7rem;
  color: var(--chess-cream);
  opacity: 0.35;
  letter-spacing: 0.08em;
}

.footer-links {
  display: flex; gap: 1.5rem;
}

.footer-links a {
  font-size: 0.7rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--chess-cream);
  opacity: 0.4;
  text-decoration: none;
  transition: opacity 0.2s;
}

.footer-links a:hover { opacity: 1; color: var(--chess-gold); }

/* ── BREADCRUMB ── */
.breadcrumb {
  display: flex; align-items: center; gap: 0.5rem;
  font-size: 0.7rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--chess-cream);
  opacity: 0.45;
  margin-bottom: 2rem;
}

.breadcrumb a { color: inherit; text-decoration: none; transition: color 0.2s; }
.breadcrumb a:hover { color: var(--chess-gold); opacity: 1; }
.breadcrumb-sep { color: var(--chess-gold-dim); }

/* ── DIVIDER ── */
.chess-divider {
  display: flex; align-items: center; gap: 1rem;
  margin: 2.5rem 0;
  color: var(--chess-gold-dim);
  font-size: 1rem;
}

.chess-divider::before, .chess-divider::after {
  content: '';
  flex: 1; height: 1px;
  background: var(--chess-border);
}

/* ── ANIMATIONS ── */
@keyframes fadeUp {
  from { opacity: 0; transform: translateY(20px); }
  to   { opacity: 1; transform: translateY(0); }
}

.fade-up { animation: fadeUp 0.5s ease both; }
.fade-up-1 { animation-delay: 0.1s; }
.fade-up-2 { animation-delay: 0.2s; }
.fade-up-3 { animation-delay: 0.3s; }
.fade-up-4 { animation-delay: 0.4s; }

/* ── RESPONSIVE ── */
@media (max-width: 900px) {
  .site-main {
    grid-template-columns: 1fr;
    padding: 2rem 1.5rem;
  }
  .main-content { padding-right: 0; margin-bottom: 3rem; }
  .site-sidebar { border-left: none; border-top: 1px solid var(--chess-border); padding-left: 0; padding-top: 2rem; }
  .site-header { padding: 0 1.5rem; }
  .site-nav { display: none; }
  .post-card-featured { flex-direction: column; }
  .post-card-featured .card-img { width: 100%; }
}
